def run(self):
    '''
    The main executor entrypoint, where we determine if the specified
    task requires looping and either runs the task with self._run_loop()
    or self._execute(). After that, the returned results are parsed and
    returned as a dict.
    '''

    display.debug("in run() - task %s" % self._task._uuid)

    try:
        try:
            items = self._get_loop_items()
        except AnsibleUndefinedVariable as e:
            # save the error raised here for use later
            items = None
            self._loop_eval_error = e

        if self._loop_eval_error is None and (items is None or items):
            self._resolve_delegation(items)

        if items is not None:
            if len(items) > 0:
                item_results = self._run_loop(items)

                # create the overall result item
                res = dict(results=item_results)

                # loop through the item results and set the global changed/failed/skipped result flags based on any item.
                res['skipped'] = True
                for item in item_results:
                    if 'changed' in item and item['changed'] and not res.get('changed'):
                        res['changed'] = True
                    if res['skipped'] and ('skipped' not in item or ('skipped' in item and not item['skipped'])):
                        res['skipped'] = False
                    if 'failed' in item and item['failed']:
            raise AnsibleError("Unexpected failure in finding the lookup named '%s' in the available lookup plugins" % self._task.loop_with)

    elif self._task.loop is not None:
        items = templar.template(self._task.loop)
        if not isinstance(items, list):
            raise AnsibleError(
                "Invalid data passed to 'loop', it requires a list, got this instead: %s."
                " Hint: If you passed a list/dict of just one element,"
                " try adding wantlist=True to your lookup invocation or use q/query instead of lookup." % items
            )

    return items

def _resolve_delegation(self, items):
    if self._task.delegate_to is None or self._variable_manager is None:
        return

    variables = self._job_vars
    if items and items[0] is not None:
        # A delegate target may use the loop variable. Resolve it once,
        # before executing the task for any of the loop items.
        variables = variables.copy()
        variables[self._task.loop_control.loop_var] = items[0]

    templar = Templar(loader=self._loader, variables=variables)
    delegated_vars, delegated_host_name = self._variable_manager.get_delegated_vars_and_hostname(
        templar=templar,
        task=self._task,
        variables=variables,
    )
    if delegated_host_name is not None:
        self._task.delegate_to = delegated_host_name
        self._job_vars['ansible_delegated_vars'] = delegated_vars

def _run_loop(self, items):
    '''
    Runs the task with the loop items specified and collates the result
    into an array named 'results' which is inserted into the final result
    along with the item for which the loop ran.
    '''
    task_vars = self._job_vars
    # Set options vars
    for option, option_value in self._options_vars.items():
        variables[option] = option_value

    if self._hostvars is not None and include_hostvars:
        variables['hostvars'] = self._hostvars

    return variables

def get_delegated_vars_and_hostname(self, templar, task, variables):
    """Return delegated host variables and the templated delegation target."""
    delegated_vars = {}
    delegated_host_name = None

    if task.delegate_to is None:
        return delegated_vars, delegated_host_name

    delegated_host_name = templar.template(task.delegate_to, fail_on_undefined=False)
    if delegated_host_name is None:
        raise AnsibleError(message="Undefined delegate_to host for task:", obj=task._ds)
    if not isinstance(delegated_host_name, string_types):
        raise AnsibleError(message="the field 'delegate_to' has an invalid type (%s), and could not be"
                                   " converted to a string type." % type(delegated_host_name), obj=task._ds)

    delegated_host = None
    if self._inventory is not None:
        delegated_host = self._inventory.get_host(delegated_host_name)
        if delegated_host is None:
            for host in self._inventory.get_hosts(ignore_limits=True, ignore_restrictions=True):
                if host.address == delegated_host_name:
                    delegated_host = host
                    break
            else:
                delegated_host = Host(name=delegated_host_name)
    else:
        delegated_host = Host(name=delegated_host_name)

    delegated_vars[delegated_host_name] = self.get_vars(
        play=task.get_play(),
        host=delegated_host,
        task=task,
        include_delegate_to=False,
        include_hostvars=True,
    )
    delegated_vars[delegated_host_name]['inventory_hostname'] = variables.get('inventory_hostname')

    return delegated_vars, delegated_host_name

